#pragma once
// Generated-equivalent of FastSIMD's simd_lib_config.h.in for the
// FastSIMD_FastNoise dispatch library.
//
// Upstream, this header is generated by the
// fastsimd_create_dispatch_library() CMake function and lists every ISA
// feature set compiled into the dispatch library. We replicate it here
// so the dispatch machinery builds without CMake.
//
// Currently only the SSE2 baseline is compiled (see
// generated/FastSIMD_FastNoise_SSE2.cpp). This is correct on every x86-64
// CPU; add more feature sets if profiling warrants it.

#include <FastSIMD/Utility/ArchDetect.h>
#include <FastSIMD/Utility/FeatureSetList.h>

namespace FastSIMD
{
namespace FastSIMD_FastNoise
{
using CompiledFeatureSets = FeatureSetList<0
, FeatureSet::SSE2
>;
} // namespace FastSIMD_FastNoise
} // namespace FastSIMD
